import React from 'react';
import { Briefcase, TrendingUp, Users } from 'lucide-react';

const recruiters = [
    { name: "TCS", logo: "TCS" },
    { name: "Infosys", logo: "Infosys" },
    { name: "Wipro", logo: "Wipro" },
    { name: "Cognizant", logo: "Cognizant" },
    { name: "Accenture", logo: "Accenture" },
    { name: "IBM", logo: "IBM" },
    { name: "L&T", logo: "L&T" },
    { name: "Amazon", logo: "Amazon" },
];

const stats = [
    { label: "Placement Offers", value: "450+", icon: Briefcase },
    { label: "Top Recruiters", value: "80+", icon: Users },
    { label: "Highest Package", value: "14 LPA", icon: TrendingUp },
];

const Placement = () => {
    return (
        <section id="placement" className="py-24 bg-white overflow-hidden">
            <div className="max-w-7xl mx-auto px-6">

                <div className="flex flex-col lg:flex-row gap-16 items-center">

                    {/* Left side text */}
                    <div className="lg:w-1/2">
                        <span className="text-gold font-bold tracking-[0.2em] uppercase text-sm mb-3 block">Placements</span>
                        <h2 className="text-4xl md:text-5xl font-display font-extrabold text-coral mb-6">Empowering Careers</h2>
                        <div className="w-16 h-1.5 bg-gradient-to-r from-coral to-gold rounded-full mb-8"></div>
                        <p className="text-slate-500 font-body leading-relaxed text-lg mb-10">
                            Our dedicated placement cell ensures that students are industry-ready. With rigorous training and strong corporate tie-ups, we secure prestigious offers from top multinational companies every year.
                        </p>

                        {/* Stats grid */}
                        <div className="grid grid-cols-2 lg:grid-cols-3 gap-6">
                            {stats.map((stat, idx) => (
                                <div key={idx} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 hover:border-coral transition-colors duration-300 group">
                                    <stat.icon className="text-gold mb-4 group-hover:text-coral transition-colors duration-300" size={28} />
                                    <div className="text-3xl font-display font-bold text-coral2 mb-2">{stat.value}</div>
                                    <div className="text-xs font-bold uppercase tracking-wider text-slate-400">{stat.label}</div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Right side Marquee */}
                    <div className="lg:w-1/2 relative w-full lg:h-[400px] h-[300px] bg-slate-50 rounded-3xl border border-slate-100 shadow-inner flex flex-col justify-center overflow-hidden py-12">
                        <h3 className="text-center font-display text-xl text-coral font-bold mb-8">Our Top Recruiters</h3>

                        {/* Infinite scroll track */}
                        <style>
                        {`
                        @keyframes scrollMarquee {
                            0% { transform: translateX(0); }
                            100% { transform: translateX(calc(-150px * 8)); }
                        }
                        .animate-marquee {
                            animation: scrollMarquee 20s linear infinite;
                            flex-wrap: nowrap;
                        }
                        .animate-marquee:hover {
                            animation-play-state: paused;
                        }
                        `}
                        </style>
                        <div className="flex animate-marquee items-center gap-8 px-4 w-[calc(150px*16)]">
                            {/* Duplicate array for seamless looping */}
                            {[...recruiters, ...recruiters].map((rec, idx) => (
                                <div key={idx} className="flex-shrink-0 w-32 h-16 bg-white rounded-xl shadow-[0_4px_16px_rgba(48,54,79,0.06)] flex items-center justify-center border border-slate-100 hover:scale-105 transition-transform cursor-pointer group hover:border-gold">
                                    <span className="font-display font-bold text-slate-700 text-lg tracking-widest group-hover:text-coral">{rec.logo}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                </div>
            </div>
        </section>
    );
};

export default Placement;
